// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

interface IStargateDelegation {
    /*------- Errors -------*/
    /// @notice Error thrown when a user is not authorized to perform an action
    error UnauthorizedUser(address user);
    /// @notice Error thrown when an NFT is under the maturity period
    error NFTUnderMaturityPeriod(uint256 tokenId);
    /// @notice Error thrown when an NFT is already delegated
    error NFTAlreadyDelegated(uint256 tokenId);
    /// @notice Error thrown when an NFT is not delegated
    error NFTNotDelegated(uint256 tokenId);
    /// @notice Error thrown when there are no rewards to claim
    error NoRewardsToClaim(uint256 tokenId);
    /// @notice Error thrown when an address is the zero address
    error AddressCannotBeZero();
    /// @notice Error thrown when a vtho reward per block per NFT level is invalid
    error InvalidVthoRewardPerBlock(uint256 level, uint256 value);
    /// @notice Error thrown when a delegation period is invalid
    error InvalidDelegationPeriod();
    /// @notice Error thrown when an array is empty
    error ArrayCannotBeEmpty();
    /// @notice Error thrown when an NFT level is invalid
    error InvalidNFTLevel(uint256 tokenId, uint256 level);
    /// @notice Error thrown when there is insufficient VTHO balance for rewards claim
    error InsufficientVthoBalanceForRewardsClaim(uint256 balance, uint256 required);
    /// @notice Error thrown when a VTHO transfer fails
    error VthoTransferFailed(address recipient, uint256 amount);
    /// @notice Error thrown when the rewards accumulation period ended
    error RewardsAccumulationPeriodEnded();
    /// @notice Error thrown when the user requests to exit delegation repeatedly
    error DelegationExitAlreadyRequested();
    /// @notice Error thrown when there are no lost rewards to claim
    error NoLostRewardsToClaim(address owner, uint256 tokenId);

    /*------- Events -------*/
    /// @notice Event emitted when a delegation simulation is started
    event DelegationSimulationStarted(
        uint256 indexed tokenId,
        address indexed delegator,
        uint256 rewardsAccumulationStartBlock,
        bool indexed isDelegationForever,
        address caller
    );
    /// @notice Event emitted when a delegation exit is requested
    event DelegationExitRequested(uint256 indexed tokenId, uint256 delegationEndBlock);
    /// @notice Event emitted when a delegation rewards are claimed
    event DelegationRewardsClaimed(
        uint256 indexed tokenId,
        uint256 rewards,
        address indexed claimer,
        address indexed recipient
    );
    /// @notice Event emitted when the rewards accumulation end block is set
    event RewardsAccumulationEndBlockSet(uint256 rewardsAccumulationEndBlock);
    /// @notice Event emitted when lost rewards are added
    event LostRewardsAdded(address indexed owner, uint256 indexed tokenId, uint256 amount);
    /// @notice Event emitted when lost rewards are removed
    event LostRewardsRemoved(address indexed owner, uint256 indexed tokenId, uint256 amount);
    /// @notice Event emitted when lost rewards are claimed
    event LostRewardsClaimed(
        address indexed owner,
        uint256 indexed tokenId,
        address indexed claimer,
        uint256 amount
    );

    /*------- Functions -------*/

    function version() external view returns (uint256);

    function clock() external view returns (uint48);

    function CLOCK_MODE() external view returns (string memory);

    function delegate(uint256 _tokenId, bool _delegateForever) external;

    function requestDelegationExit(uint256 _tokenId) external;

    function claimRewards(uint256 _tokenId) external;

    function claimableRewards(uint256 _tokenId) external view returns (uint256);

    function accumulatedRewards(uint256 _tokenId) external view returns (uint256);

    function isDelegationActive(uint256 _tokenId) external view returns (bool);

    function getVthoRewardPerBlock(uint256 _level) external view returns (uint256);

    function getDelegationPeriod() external view returns (uint256);

    function getRewardsAccumulationEndBlock() external view returns (uint256);

    function getRewardsAccumulationStartBlock(uint256 _tokenId) external view returns (uint256);

    function getDelegationEndBlock(uint256 _tokenId) external view returns (uint256);

    function currentDelegationPeriodEndBlock(uint256 _tokenId) external view returns (uint256);

    function getDelegationDetails(
        uint256 _tokenId
    )
        external
        view
        returns (
            bool isDelegationActive,
            uint256 claimableRewards,
            uint256 rewardsAccumulationStartBlock,
            uint256 delegationEndBlock
        );
}

contracts/interfaces/IProtocolStaker.sol.content:
//SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IProtocolStaker {
    event ValidationQueued(
        address indexed validator,
        address indexed endorser,
        uint32 period,
        uint256 stake
    );
    event ValidationWithdrawn(address indexed validator, uint256 stake);
    event ValidationSignaledExit(address indexed validator);
    event StakeIncreased(address indexed validator, uint256 added);
    event StakeDecreased(address indexed validator, uint256 removed);
    event BeneficiarySet(address indexed validator, address beneficiary);

    event DelegationAdded(
        address indexed validator,
        uint256 indexed delegationID,
        uint256 stake,
        uint8 multiplier
    );
    event DelegationWithdrawn(uint256 indexed delegationID, uint256 stake);
    event DelegationSignaledExit(uint256 indexed delegationID);

    /**
     * @dev totalStake returns all stakes and weight by active validators.
     */
    function totalStake() external view returns (uint256 totalStake, uint256 totalWeight);

    /**
     * @dev queuedStake returns all stakes by queued validators.
     */
    function queuedStake() external view returns (uint256 queuedStake);

    /**
     * @dev addValidation creates a validation to the queue.
     */
    function addValidation(address validator, uint32 period) external payable;

    /**
     * @dev increaseStake adds VET to the current stake of the queued/active validator.
     */
    function increaseStake(address validator) external payable;

    /**
     * @dev setBeneficiary sets the beneficiary address for a validator.
     */
    function setBeneficiary(address validator, address beneficiary) external;

    /**
     * @dev decreaseStake removes VET from the current stake of an active validator
     */
    function decreaseStake(address validator, uint256 amount) external;

    /**
     * @dev allows the caller to withdraw a stake when their status is set to exited
     */
    function withdrawStake(address validator) external;

    /**
     * @dev signalExit signals the intent to exit a validator position at the end of the staking period.
     */
    function signalExit(address validator) external;

    /**
     * @dev addDelegation creates a delegation position on a validator.
     */
    function addDelegation(
        address validator,
        uint8 multiplier // (% of msg.value) 100 for x1, 200 for x2, etc. This enforces a maximum of 2.56x multiplier
    ) external payable returns (uint256 delegationID);

    /**
     * @dev exitDelegation signals the intent to exit a delegation position at the end of the staking period.
     * Funds are available once the current staking period ends.
     */
    function signalDelegationExit(uint256 delegationID) external;

    /**
     * @dev withdrawDelegation withdraws the delegation position funds.
     */
    function withdrawDelegation(uint256 delegationID) external;

    /**
     * @dev getDelegation returns the validator, stake, and multiplier of a delegation.
     */
    function getDelegation(
        uint256 delegationID
    ) external view returns (address validator, uint256 stake, uint8 multiplier, bool isLocked);

    /**
     * @dev getDelegationPeriodDetails returns the start, end period and isLocked status of a delegation.
     */
    function getDelegationPeriodDetails(
        uint256 delegationID
    ) external view returns (uint32 startPeriod, uint32 endPeriod);

    /**
     * @dev getValidation returns the validator stake. endorser, stake, weight of a validator.
     */
    function getValidation(
        address validator
    )
        external
        view
        returns (
            address endorser,
            uint256 stake,
            uint256 weight,
            uint256 queuedStake,
            uint8 status,
            uint32 offlineBlock
        );

    /**
     * @dev getValidationPeriodDetails returns the validator period details. period, startBlock, exitBlock and completed periods for a validator.
     */
    function getValidationPeriodDetails(
        address validator
    )
        external
        view
        returns (uint32 period, uint32 startBlock, uint32 exitBlock, uint32 completedPeriods);

    /**
     * @dev getWithdrawable returns the amount of a validator's withdrawable VET.
     */
    function getWithdrawable(address id) external view returns (uint256 withdrawableVET);

    /**
     * @dev firstActive returns the head validatorId of the active validators.
     */
    function firstActive() external view returns (address firstActive);

    /**
     * @dev firstQueued returns the head validatorId of the queued validators.
     */
    function firstQueued() external view returns (address firstQueued);

    /**
     * @dev next returns the validator in a linked list
     */
    function next(address prev) external view returns (address nextValidation);

    /**
     * @dev getDelegatorsRewards returns all delegators rewards for the given validator address and staking period.
     */
    function getDelegatorsRewards(
        address validator,
        uint32 stakingPeriod
    ) external view returns (uint256 rewards);

    /**
     * @dev getValidationTotals returns the total locked, total locked weight,
     * total queued, total queued weight, total exiting and total exiting weight for a validator.
     */
    function getValidationTotals(
        address validator
    )
        external
        view
        returns (
            uint256 lockedVET,
            uint256 lockedWeight,
            uint256 queuedVET,
            uint256 exitingVET,
            uint256 nextPeriodWeight
        );

    /**
     * @dev getValidationsNum returns the number of active and queued validators.
     */
    function getValidationsNum() external view returns (uint64 activeCount, uint64 queuedCount);

    /**
     * @dev issuance returns the total amount of VTHO generated for the context of current block.
     */
    function issuance() external view returns (uint256 issued);
}

contracts/interfaces/IStargate.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

interface IStargate {
    // ---------- Errors ------------ //

    error UnauthorizedUser(address user);
    error DelegationExitAlreadyRequested();
    error InvalidDelegationStatus(uint256 tokenId, DelegationStatus status);
    error DelegationNotFound(uint256 tokenId);
    error TokenUnderMaturityPeriod(uint256 tokenId);
    error InvalidToken(uint256 tokenId);
    error ValidatorNotActiveOrQueued(address validator);
    error TokenAlreadyDelegated(uint256 tokenId);
    error OnlyStargateNFTAndProtocolStaker();
    error InvalidInitializationParams();
    error VetAmountMismatch(uint8 levelId, uint256 required, uint256 provided);
    error VetTransferFailed(address receiver, uint256 amount);
    error InsufficientContractBalance(uint256 contractBalance, uint256 tokenAmount);
    error MaxClaimablePeriodsExceeded();
    error InvalidMaxClaimablePeriods();

    // ---------- Events ------------ //

    /// @notice Emitted when a delegation is initiated
    /// @param tokenId The ID of the token that was delegated
    /// @param validator The validator that was delegated to
    /// @param delegationId The ID of the delegation
    /// @param amount The amount of VET delegated
    /// @param levelId The level ID of the token
    /// @param probabilityMultiplier The probability multiplier of the delegation
    event DelegationInitiated(
        uint256 indexed tokenId,
        address indexed validator,
        uint256 indexed delegationId,
        uint256 amount,
        uint8 levelId,
        uint8 probabilityMultiplier
    );

    /// @notice Emitted when a delegation exit is requested
    /// @dev When the delegation is pending, exit is immediate and this event is emitted
    /// @param tokenId The ID of the token that was delegated
    /// @param validator The validator that was delegated to
    /// @param delegationId The ID of the delegation
    /// @param exitPeriod The period at which the delegation exit will be processed,
    /// in case the delegation is pending it will be the current block
    event DelegationExitRequested(
        uint256 indexed tokenId,
        address indexed validator,
        uint256 indexed delegationId,
        uint48 exitPeriod
    );

    /// @notice Emitted when a delegation is withdrawn
    /// @dev This is emitted when the delegation is withdrawn, either because the user requested to exit
    /// or because the delegation is called with a new validator or if requestDelegationExit is called
    /// the delegation is still pending.
    /// @param tokenId The ID of the token that was delegated
    /// @param validator The validator that was delegated to
    /// @param delegationId The ID of the delegation
    /// @param amount The amount of VET withdrawn
    /// @param levelId The level ID of the token
    event DelegationWithdrawn(
        uint256 indexed tokenId,
        address indexed validator,
        uint256 indexed delegationId,
        uint256 amount,
        uint8 levelId
    );

    /// @notice Emitted when rewards are claimed
    /// @param receiver The address that claimed the rewards
    /// @param tokenId The ID of the token that claimed the rewards
    /// @param delegationId The ID of the delegation that claimed the rewards
    /// @param amount The amount of rewards claimed
    /// @param firstClaimedPeriod The first period that the rewards were claimed for
    /// @param lastClaimedPeriod The last period that the rewards were claimed for
    event DelegationRewardsClaimed(
        address indexed receiver,
        uint256 indexed tokenId,
        uint256 indexed delegationId,
        uint256 amount,
        uint32 firstClaimedPeriod,
        uint32 lastClaimedPeriod
    );

    /// @notice Emitted when the max claimable periods are set
    /// @param maxClaimablePeriods The new max claimable periods
    event MaxClaimablePeriodsSet(uint32 maxClaimablePeriods);

    // ---------- Data Types ------------ //

    struct Delegation {
        uint256 delegationId; // the latest delegation id for the token (can be pending, active, or exited)
        address validator; // the validator address
        uint256 stake; // the amount of VET delegated to the validator (that is the same as the price of the NFT)
        uint8 probabilityMultiplier; // a multiplier used to multiply the stake of the user when calculating the weight of the delegation (scaled by 100)
        uint32 startPeriod; // the period when the delegation became active
        uint32 endPeriod; // the period when the delegation ended (if exited); uint32.max if still active
        bool isLocked; // the delegation is locked while active, and it means that the VET cannot be withdrawn and user needs to request to exit
        DelegationStatus status;
    }

    /// @notice The status of a delegation returned by the StargateStaker contract
    /// @dev NONE: the delegation id is not valid, or user never delegated
    /// @dev PENDING: the user has selected a validator and staked the VET, but is waiting for the next period to start or for the validator to be become active
    /// @dev ACTIVE: the user is accumulating rewards; if the user requests to exit the delegation the status remains ACTIVE
    /// @dev EXITED: the user has exited the delegation or the validator exited and forced the user to exit or the user exited a pending delegation and the stake is now 0
    enum DelegationStatus {
        NONE,
        PENDING,
        ACTIVE,
        EXITED
    }

    // ---------- Pausable ------------ //

    /// @notice Pauses the StargateNFT contract
    /// @dev Only the DEFAULT_ADMIN_ROLE can call this function
    /// @dev Pausing the contract will prevent minting
    function pause() external;

    /// @notice Unpauses the StargateNFT contract
    /// @dev Only the DEFAULT_ADMIN_ROLE can call this function
    function unpause() external;

    // ---------- Staking ------------ //

    /// @notice Stakes VET and mints an NFT
    /// @param _levelId The ID of the token level to mint, VET as msg.value
    /// @return tokenId The ID of the minted NFT
    function stake(uint8 _levelId) external payable returns (uint256 tokenId);

    /// @notice Unstakes a token from the Stargate contract, will return the VET to the user and burn the NFT
    /// for token to be unstaked, its delegation status must not be ACTIVE
    /// @param _tokenId The ID of the token to unstake
    /// @dev Emits a {IStargate.TokenUnstaked} event
    function unstake(uint256 _tokenId) external;

    // ---------- Delegations ------------ //

    /// @notice Delegates the token to the validator to increase its probability of being selected as
    /// a validator and accumulate rewards for each mined block.
    /// The amount of rewards depends on the effective stake compared to the total effective stake of the validator.
    /// The delegation is not active until the start of the next period of the validator. In the meantime, the user
    /// can change the validator by calling this function again, cancel the delegation or unstaking the token.
    /// Once the delegation is active, the user can request to exit the delegation by calling requestDelegationExit.
    /// The token will remain delegated until the end of the validator period end block.
    ///
    /// This contract will need to move the VET associated to the token from the StargateNFT contract and deposit
    /// it in the protocol staking contract.
    /// If the token was previously delegated, the VET will be moved from the protocol staking contract to this contract
    /// again and then moved back to the protocol staking contract.
    ///
    /// @param _tokenId - the token ID to delegate
    /// @param _validator - the validator to delegate to
    function delegate(uint256 _tokenId, address _validator) external;

    /// @notice Stakes VET and mints an NFT, and delegates it
    /// @param _levelId The ID of the token level to mint, VET as msg.value
    /// @param _validator The validator to delegate to
    /// @return tokenId The ID of the minted NFT
    function stakeAndDelegate(
        uint8 _levelId,
        address _validator
    ) external payable returns (uint256 tokenId);

    /// @notice Migrates a token from the legacy nodes contract to StargateNFT, and delegates it
    /// @param _tokenId The ID of the token to migrate
    /// @param _validator The validator to delegate to
    function migrateAndDelegate(uint256 _tokenId, address _validator) external payable;

    /// @notice Requests a delegation exit by signalling the exit to the protocol staking contract.
    /// If the delegation is active, the user will need to wait for then end of the period to actually exit, if instead
    /// the delegation is pending the user will exit immediatly.
    /// Once the request to exit is signalled, the user cannot undo it and cannot request to exit again.
    /// @dev Exiting a pending delegation, differs from exiting an active delegation.
    /// In the first case, it is enough to withdraw the VET from the protocol, in the second case
    /// we will signal to the protocol to exit the delegation.
    /// @param _tokenId - the token ID to request the exit for
    function requestDelegationExit(uint256 _tokenId) external;

    /// @notice Returns the details of the delegation of a token
    /// @dev If the token does not have any delegation, it will return a set of default values
    /// @param _tokenId - the token ID
    /// @return The details of the delegation
    function getDelegationDetails(uint256 _tokenId) external view returns (Delegation memory);

    /// @notice Will fetch the latest delegation of a token and will return its status
    /// @param _tokenId - the token ID
    /// @return The status of the delegation
    function getDelegationStatus(uint256 _tokenId) external view returns (DelegationStatus);

    /// @notice Will return the latest delegation id of a token (regardless of its status)
    /// @param _tokenId - the token ID
    /// @return The delegation id
    function getDelegationIdOfToken(uint256 _tokenId) external view returns (uint256);

    /// @notice Will return true if the user has requested to exit the latest delegation (regardless of its status)
    /// @dev This will return true even if the delegation is EXITED
    /// @param _tokenId - the token ID
    /// @return True if the user has requested to exit the delegation
    function hasRequestedExit(uint256 _tokenId) external view returns (bool);

    /// @notice Returns the total effective stake of the delegators of a validator in a specific period
    /// @param _validator - the validator address
    /// @param _period - the period to check
    /// @return The total effective stake of the delegators of the validator in the period
    function getDelegatorsEffectiveStake(
        address _validator,
        uint32 _period
    ) external view returns (uint256);

    /// @notice Returns the effective stake of a token
    /// @dev The effective stake is the amount of VET that is staked by the token multiplied
    /// by the reward multiplier of the level, and is used to calculate the share of the delegator in the period.
    /// @param _tokenId - the token ID
    /// @return The effective stake of the token
    function getEffectiveStake(uint256 _tokenId) external view returns (uint256);

    // ---------- Rewards ------------ //

    /// @notice Claims all the rewards for a token
    /// @dev This function will claim the rewards for each period between the last
    /// claimed period and the last claimable period.
    /// @param _tokenId - the token ID
    function claimRewards(uint256 _tokenId) external;

    /// @notice Returns the claimable rewards for a token for batch 0 (first 832 periods)
    /// @dev This is the sum of the claimable rewards for each period between the last claimed period and the last claimable period.
    /// @param _tokenId - the token ID
    /// @return The claimable rewards for the token
    function claimableRewards(uint256 _tokenId) external view returns (uint256);

    /// @notice Returns the claimable rewards for a token for a specific batch
    /// @dev This is the sum of the claimable rewards for each period between the last claimed period and the last claimable period.
    /// @param _tokenId - the token ID
    /// @param _batch - the batch to check
    /// @return The claimable rewards for the token
    function claimableRewards(uint256 _tokenId, uint32 _batch) external view returns (uint256);

    /// @notice Returns the locked rewards for a token
    /// @dev When the delegation is active, the rewards rewards of the current period are locked
    /// and cannot be claimed until the next period. This function retur
    /// @param _tokenId - the token ID
    /// @return The locked rewards for the token
    function lockedRewards(uint256 _tokenId) external view returns (uint256);

    /// @notice Returns the latestClaimedPeriod and the endPeriod of the latest delegation of a token
    /// @param _tokenId - the token ID
    /// @return lastClaimedPeriod - the latest claimed period
    /// @return endPeriod - the end period of the latest delegation
    function claimableDelegationPeriods(uint256 _tokenId) external view returns (uint32, uint32);

    // ---------- Max Claimable Periods ---------- //

    /// @notice Returns the max claimable periods
    /// @return The max claimable periods
    function getMaxClaimablePeriods() external view returns (uint32);

    /// @notice Sets the max claimable periods
    /// @param _maxClaimablePeriods - the max claimable periods
    function setMaxClaimablePeriods(uint32 _maxClaimablePeriods) external;

    // ---------- Clock ------------ //

    /// @notice Returns the current clock
    /// @dev Call CLOCK_MODE() to know if the clock is in timestamp or block mode
    function clock() external view returns (uint48);

    /// @notice Returns the clock mode
    /// @dev Call clock() to know the current clock
    function CLOCK_MODE() external view returns (string memory);

    // ---------- Contracts ---------- //

    /// @notice Returns the address of the protocol staking contract
    /// @return The address of the protocol staking contract
    function getProtocolStakerContract() external view returns (address);

    /// @notice Returns the address of the StargateNFT contract
    /// @return The address of the StargateNFT contract
    function getStargateNFTContract() external view returns (address);
}

contracts/interfaces/IStargateNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import { IERC721 } from "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import { IERC721Enumerable } from "@openzeppelin/contracts/token/ERC721/extensions/IERC721Enumerable.sol";
import { IERC165 } from "@openzeppelin/contracts/utils/introspection/IERC165.sol";
import { DataTypes } from "../StargateNFT/libraries/DataTypes.sol";
import { ITokenAuction } from "./ITokenAuction.sol";

interface IStargateNFT is IERC165, IERC721, IERC721Enumerable {
    // ------------------ Events ------------------ //

    /**
     * @notice Emitted when a token level is updated
     * @param levelId The ID of the level that was updated
     * @param name The new name of the level
     * @param isX The new X status
     * @param maturityBlocks The new maturity period in blocks
     * @param scaledRewardFactor The new scaled reward multiplier
     * @param vetAmountRequiredToStake The new VET amount required for staking
     */
    event LevelUpdated(
        uint8 indexed levelId,
        string name,
        bool isX,
        uint64 maturityBlocks,
        uint64 scaledRewardFactor,
        uint256 vetAmountRequiredToStake
    );

    /**
     * @notice Emitted when the circulating supply of a token level is updated
     * @param levelId The ID of the level supply that was updated
     * @param oldCirculatingSupply The old circulating supply
     * @param newCirculatingSupply The new circulating supply
     */
    event LevelCirculatingSupplyUpdated(
        uint8 indexed levelId,
        uint208 oldCirculatingSupply,
        uint208 newCirculatingSupply
    );

    /**
     * @notice Emitted when the cap of a token level is updated
     * @param levelId The ID of the level cap that was updated
     * @param oldCap The old cap
     * @param newCap The new cap
     */
    event LevelCapUpdated(uint8 indexed levelId, uint32 oldCap, uint32 newCap);

    /**
     * @notice Emitted when the boost price per block of a token level is updated
     * @param levelId The ID of the level boost price per block that was updated
     * @param oldBoostPricePerBlock The old boost price per block
     * @param newBoostPricePerBlock The new boost price per block
     */
    event LevelBoostPricePerBlockUpdated(
        uint8 indexed levelId,
        uint256 oldBoostPricePerBlock,
        uint256 newBoostPricePerBlock
    );

    /**
     * @notice Emitted when an NFT is minted
     * @param owner The address that owns the newly minted NFT
     * @param levelId The level ID of the newly minted NFT
     * @param migrated Whether the token was migrated from legacy nodes contract
     * @param tokenId The ID of the newly minted NFT
     * @param vetAmountStaked The amount of VET staked to mint the NFT
     */
    event TokenMinted(
        address indexed owner,
        uint8 indexed levelId,
        bool indexed migrated,
        uint256 tokenId,
        uint256 vetAmountStaked
    );

    /**
     * @notice Emitted when an NFT is burned
     * @param owner The address that owns the newly burned NFT
     * @param levelId The level ID of the newly burned NFT
     * @param tokenId The ID of the newly burned NFT
     * @param vetAmountStaked The amount of VET staked to burn the NFT
     */
    event TokenBurned(
        address indexed owner,
        uint8 indexed levelId,
        uint256 tokenId,
        uint256 vetAmountStaked
    );

    /**
     * @notice Emitted when the base URI for the token metadata is updated
     * @param oldBaseURI The old base URI
     * @param newBaseURI The new base URI
     */
    event BaseURIUpdated(string oldBaseURI, string newBaseURI);

    /**
     * @notice Emitted when a token manager is added to a token
     * @param tokenId The ID of the token
     * @param manager The address of the manager
     */
    event TokenManagerAdded(uint256 indexed tokenId, address indexed manager);

    /**
     * @notice Emitted when a token manager is removed from a token
     * @param tokenId The ID of the token
     * @param manager The address of the manager
     */
    event TokenManagerRemoved(uint256 indexed tokenId, address indexed manager);

    /** ------------------ Deprecated Events ------------------ */
    // These events are deprecated in V3 but we
    // keep them for backwards compatibility and
    // for indexing purposes

    /**
     * @notice Emitted when VTHO rewards are claimed for a token
     * @dev Not emitted anymore in V3, since we don't generate VTHO anymore
     * @param owner The address that claimed the rewards
     * @param tokenId The ID of the token for which rewards were claimed
     * @param amount The amount of VTHO rewards claimed
     * @dev Deprecated in V3
     */
    event BaseVTHORewardsClaimed(address indexed owner, uint256 indexed tokenId, uint256 amount);

    /**
     * @notice Emitted when the VTHO generation end timestamp is updated
     * @dev Not emitted anymore in V3, since there is no need to set this value anymore
     * @param oldVthoGenerationEndTimestamp The old VTHO generation end timestamp
     * @param newVthoGenerationEndTimestamp The new VTHO generation end timestamp
     */
    event VthoGenerationEndTimestampSet(
        uint48 oldVthoGenerationEndTimestamp,
        uint48 newVthoGenerationEndTimestamp
    );

    // ------------------ Constants ------------------ //

    /// @notice Returns the reward multiplier scaling factor
    /// @return REWARD_MULTIPLIER_SCALING_FACTOR - the reward multiplier scaling factor
    function REWARD_MULTIPLIER_SCALING_FACTOR() external view returns (uint256);

    // ------------------ Functions ------------------ //

    function version() external view returns (uint256);

    /*------- Callbacks -------*/

    /// @notice Callback function to ERC721Upgradeable._safeMint, called by StargateNFTMinting.stake
    /// @dev Only the StargateNFT contract can call this function
    /// @param to - the address to mint the token to
    /// @param tokenId - the token ID of the token to mint
    function _safeMintCallback(address to, uint256 tokenId) external;

    /// @notice Callback function to ERC721Upgradeable._burn, called by StargateNFTMinting.unstake
    /// @dev Only the StargateNFT contract can call this function
    /// @param tokenId - the token ID of the token to burn
    function _burnCallback(uint256 tokenId) external;

    /*------- Pausing Functions -------*/

    /// @notice Pauses the StargateNFT contract
    /// @dev Only the PAUSER_ROLE can call this function
    /// @dev Pausing the contract will prevent minting
    function pause() external;

    /// @notice Unpauses the StargateNFT contract
    /// @dev Only the PAUSER_ROLE can call this function
    function unpause() external;

    /*------- Level Functions -------*/

    /// @notice Adds a new token level
    /// @param _levelAndSupply - The level and supply to add, see {DataTypes.LevelAndSupply}
    /// @param _boostPricePerBlock - The boost price per block for the level
    /// @dev Only the LEVEL_OPERATOR_ROLE can call this function
    /// Check the {Levels.addLevel} library function for more details
    /// Emits a {IStargateNFT.LevelUpdated} event
    /// Emits a {IStargateNFT.LevelCirculatingSupplyUpdated} event
    /// Emits a {IStargateNFT.LevelCapUpdated} event
    /// Emits a {IStargateNFT.LevelBoostPricePerBlockUpdated} event
    function addLevel(
        DataTypes.LevelAndSupply memory _levelAndSupply,
        uint256 _boostPricePerBlock
    ) external;

    /// @notice Returns a list of all token level spec IDs
    /// @return levelIds - The list of token level spec IDs
    function getLevelIds() external view returns (uint8[] memory);

    /// @notice Returns a token level spec for a given level ID
    /// @param _levelId The ID of the token level spec to return
    /// @return Level - The token level spec
    function getLevel(uint8 _levelId) external view returns (DataTypes.Level memory);

    /// @notice Returns a list of all token level specs
    /// @return levels - The list of token level specs
    function getLevels() external view returns (DataTypes.Level[] memory);

    /// @notice Returns the circulating supply for all levels
    /// @return circulatingSupplies An array of circulating supply values for all levels, sorted by level id
    function getLevelsCirculatingSupplies() external view returns (uint208[] memory);

    /// @notice Returns the circulating supply and cap for a given token level
    /// @param _levelId The ID of the token level to get supply data for
    /// @return circulating The circulating supply of the token level
    /// @return cap The cap of the token level
    function getLevelSupply(uint8 _levelId) external view returns (uint208 circulating, uint32 cap);

    /// @notice Returns the circulating supply for a given level at a specific block
    /// @param _levelId The ID of the level to get supply data for
    /// @param _blockNumber The block number to get the supply at
    /// @return circulatingSupply The circulating supply of the level at the specified block
    function getCirculatingSupplyAtBlock(
        uint8 _levelId,
        uint48 _blockNumber
    ) external view returns (uint208);

    /// @notice Returns the circulating supply for all levels at a certain block
    /// @param _blockNumber The block number to get the supply at
    /// @return circulatingSupplies An array of circulating supply values for all levels, sorted by level id
    function getLevelsCirculatingSuppliesAtBlock(
        uint48 _blockNumber
    ) external view returns (uint208[] memory);

    // ---------- Token Functions ---------- //

    /// @notice Get the latest token id that was minted
    /// @dev Ids start from the total supply of the legacy contrat
    /// @return currentTokenId the latest token id that was minted
    function getCurrentTokenId() external view returns (uint256);

    /// @notice Returns a token for a given token ID
    /// @param _tokenId The ID of the token to get
    /// @return token The token
    function getToken(uint256 _tokenId) external view returns (DataTypes.Token memory);

    /// @notice Returns the level ID of a given token
    /// @param _tokenId - the token ID of the NFT
    /// @return levelId - the level ID of the NFT
    function getTokenLevel(uint256 _tokenId) external view returns (uint8);

    /// @notice Returns the tokens owned by an address
    /// @dev WARNING: This function contains external calls in a loop.
    ///      This pattern is necessary due to ERC721Enumerable's token iteration model.
    ///      This function may run out of gas if the owner has a lot of tokens.
    /// @param _owner The address to get tokens for
    /// @return tokens An array of tokens owned by the address
    function tokensOwnedBy(address _owner) external view returns (DataTypes.Token[] memory);

    /// @notice Returns the total VET staked by an address
    /// @dev WARNING: This function contains external calls in a loop.
    ///      This pattern is necessary due to ERC721Enumerable's token iteration model.
    ///      This function may run out of gas if the owner has a lot of tokens.
    /// @param _owner The address to get total VET staked for
    /// @return totalVetStaked The total VET staked by the address
    function ownerTotalVetStaked(address _owner) external view returns (uint256);

    /// @notice Returns a list of token IDs for a given owner
    /// @dev WARNING: This function contains external calls in a loop.
    ///      This pattern is necessary due to ERC721Enumerable's token iteration model.
    ///      This function may run out of gas if the owner has a lot of tokens.
    /// @param _owner The address of the owner to get token IDs for
    /// @return tokenIds The list of token IDs
    function idsOwnedBy(address _owner) external view returns (uint256[] memory);

    /// @notice Returns true if a token exists
    /// @param _tokenId The ID of the token to check
    /// @return True if the token exists, false otherwise
    function tokenExists(uint256 _tokenId) external view returns (bool);

    // ---------- Boosting Functions ------------ //

    /// @notice Boosts the maturity period of a token
    /// @dev This can only be called by the Stargate contract
    /// @param _tokenId The ID of the token to boost
    /// @dev Emits a {IStargateNFT.MaturityPeriodBoosted} event
    function boost(uint256 _tokenId) external;

    /// @notice Returns the amount of VTHO required to boost a token's maturity period
    /// @param _tokenId The ID of the token to boost
    /// @return boostAmount The amount of VTHO required to boost the token's maturity period
    function boostAmount(uint256 _tokenId) external view returns (uint256);

    /// @notice Returns the amount of VTHO required to boost a token's maturity period
    /// @param _levelId The level ID of the token to boost
    /// @return boostAmount The amount of VTHO required to boost the token's maturity period
    function boostAmountOfLevel(uint8 _levelId) external view returns (uint256);

    /// @notice Returns the boost price per block for a given level
    /// @param _levelId The level ID of the token to boost
    /// @return boostPricePerBlock The boost price per block for the level
    function boostPricePerBlock(uint8 _levelId) external view returns (uint256);

    /// @notice Returns the maturity period end block for a given token
    /// @param _tokenId The ID of the token to get maturity period end block for
    /// @return maturityPeriodEndBlock The maturity period end block
    function maturityPeriodEndBlock(uint256 _tokenId) external view returns (uint64);

    /// @notice Returns true if a token is in the maturity period
    /// @param _tokenId The ID of the token to check
    /// @return isInMaturityPeriod True if the token is in the maturity period, false otherwise
    function isUnderMaturityPeriod(uint256 _tokenId) external view returns (bool);

    // ---------- Token Manager Functions ---------- //

    /// @notice Adds a manager to a token
    /// @dev This manager can use the token for voting on VeVote
    /// or in B3TR but it cant calim rewards for themselves, transfer,
    /// delegate or unstake the token
    /// @dev If a token already has a manager, it will be removed and
    /// the new manager will be added
    /// @param _manager The address of the manager to add
    /// @param _tokenId The ID of the token to add the manager to
    /// @dev Emits a {IStargateNFT.TokenManagerAdded} event
    function addTokenManager(address _manager, uint256 _tokenId) external;

    /// @notice Removes a manager from a token
    /// @dev This manager can no longer use the token for voting on VeVote
    /// or in B3TR but it can still claim rewards for themselves, transfer,
    /// delegate or unstake the token
    /// @dev If a token has no manager, it will revert
    /// @param _tokenId The ID of the token to remove the manager from
    /// @dev Emits a {IStargateNFT.TokenManagerRemoved} event
    function removeTokenManager(uint256 _tokenId) external;

    /// @notice Returns the manager of a token, if the token does not have a manager
    /// it will return the owner of the token
    /// @param _tokenId The ID of the token to get the manager for
    /// @return manager The manager of the token
    function getTokenManager(uint256 _tokenId) external view returns (address);

    /// @notice Returns the list of:
    /// 1) Token ids managed by the user
    /// 2) Token ids owned by the user and not managed by someone else
    /// Token ids owned by the user, but managed by others, won't be returned
    /// @dev WARNING: This function contains external calls in a loop.
    ///      This pattern is necessary due to ERC721Enumerable's token iteration model.
    ///      This function may run out of gas if the user has a lot of tokens.
    /// @param _user The address of the user to get the tokens for
    /// @return tokenIds The list of token ids managed by the user
    function idsManagedBy(address _user) external view returns (uint256[] memory);

    /// @notice Returns the list of:
    /// 1) Tokens managed by the user
    /// 2) Tokens owned by the user and not managed by someone else
    /// Tokens owned by the user, but managed by others, won't be returned
    /// @dev WARNING: This function contains external calls in a loop.
    ///      This pattern is necessary due to ERC721Enumerable's token iteration model.
    ///      This function may run out of gas if the user has a lot of tokens.
    /// @param _user The address of the user to get the tokens for
    /// @return tokens The list of tokens managed by the user
    function tokensManagedBy(address _user) external view returns (DataTypes.Token[] memory);

    /// @notice Checks if an address is a manager of a token
    /// @param _manager The address of the manager to check
    /// @param _tokenId The ID of the token to check
    /// @return True if the address is a manager of the token, false otherwise
    function isTokenManager(address _manager, uint256 _tokenId) external view returns (bool);

    /// @notice Checks if a token is managed by the owner
    /// @param _tokenId The ID of the token to check
    /// @return True if the token is managed by the owner, false otherwise
    function isManagedByOwner(uint256 _tokenId) external view returns (bool);

    /// @notice Function to get the overview of the tokens related to a user
    /// A token is related to a user if it is owned by the user or if it is managed by the user
    /// This includes:
    /// - Tokens owned by the user and managed by the user
    /// - Tokens owned by the user and not managed by the user
    /// - Tokens managed by the user and not owned by the user
    /// @dev WARNING: This function contains external calls in a loop.
    ///      This pattern is necessary due to ERC721Enumerable's token iteration model.
    ///      This function may run out of gas if the user has a lot of tokens.
    /// @param _user The address of the user to get the overview of the tokens
    /// @return DataTypes.TokenOverview[] The overview of the tokens related to the user
    function tokensOverview(address _user) external view returns (DataTypes.TokenOverview[] memory);

    // ---------- Base URI Functions ---------- //

    /// @notice Sets the base URI for the token collection metadata
    /// @dev Only the MANAGER_ROLE can call this function
    /// @dev Metadata is hosted on IPFS, and the base URI is the base path to the collection metadata
    /// @param _baseTokenURI The new base URI
    /// @dev Emits a {IStargateNFT.BaseURIUpdated} event
    function setBaseURI(string memory _baseTokenURI) external;

    /// @notice Returns the base URI for the token collection metadata
    /// @return baseURI - the base URI string
    function baseURI() external view returns (string memory);

    // ---------- Stargate functions ---------- //

    /// @notice Mints a token from the StargateNFT contract
    /// @dev This can only be called by the Stargate contract
    /// @param _levelId The ID of the token level to mint
    /// @param _to The address to mint the token to
    /// @dev Emits a {IStargateNFT.TokenMinted} event
    function mint(uint8 _levelId, address _to) external returns (uint256 tokenId);

    /// @notice Burns a token from the StargateNFT contract
    /// @dev This can only be called by the Stargate contract
    /// @param _tokenId The ID of the token to burn
    /// @dev Emits a {IStargateNFT.TokenBurned} event
    function burn(uint256 _tokenId) external;

    /// @notice Migrates a token from the legacy nodes contract to StargateNFT to the same owner address
    /// as the owner of the token in the legacy nodes contract
    /// @dev This can only be called by the Stargate contract
    /// @param _tokenId The ID of the token to migrate
    /// @dev Emits a {IStargateNFT.TokenMinted} event and a {IStargateNFT.TokenMigrated} event
    function migrate(uint256 _tokenId) external;

    /// @notice Boosts the maturity period of a token
    /// @dev This can only be called by the Stargate contract
    /// @param _sender The address to boost the token for
    /// @param _tokenId The ID of the token to boost
    /// @dev Emits a {IStargateNFT.MaturityPeriodBoosted} event
    function boostOnBehalfOf(address _sender, uint256 _tokenId) external;

    /// @notice Returns the address of the Stargate contract
    /// @return stargate - the Stargate contract
    function getStargate() external view returns (address);

    // ---------- Clock Functions ---------- //

    /// @notice Returns the current block number
    /// @return blockNumber - the current block number
    function clock() external view returns (uint48);

    /// @notice Returns the clock mode
    function CLOCK_MODE() external view returns (string memory);

    /// @notice Returns the current timestamp
    /// @return timestamp - the current timestamp
    function timestamp() external view returns (uint48);

    // ---------- VTHO Functions ---------- //

    /// @notice Returns the address of the VTHO token contract
    /// @return vthoToken - the VTHO token contract
    function getVthoTokenAddress() external view returns (address);

    // ---------- Legacy Nodes Functions ---------- //

    /// @notice Returns the number of X tokens in circulation
    /// @dev Get the count of normal tokens by subtracting the count of X tokens from the total supply
    /// @return xTokensCount - the number of X tokens
    function xTokensCount() external view returns (uint208);

    /// @notice Checks if an owner owns an X token
    /// @dev WARNING: This function contains external calls in a loop.
    ///      This pattern is necessary due to ERC721Enumerable's token iteration model.
    ///      This function may run out of gas if the owner has a lot of tokens.
    /// @param _owner The address of the owner to check
    /// @return True if the owner owns an X token, false otherwise
    function ownsXToken(address _owner) external view returns (bool);

    /// @notice Checks if a token is an X token
    /// @param _tokenId The ID of the token to check
    /// @return True if the token is an X token, false otherwise
    function isXToken(uint256 _tokenId) external view returns (bool);

    /// @notice Returns the legacy nodes contract
    /// @return legacyNodes - the legacy nodes contract
    function legacyNodes() external view returns (ITokenAuction);

    // ---------- Temporary Functions ---------- //

    /// @notice Transfers the balance of the contract to the Stargate contract
    /// @dev This function was created after the refactor on the StargateNFT and Stargate
    /// contracts. After the refactor, all VET is handled by Stargate, this means
    /// stake, stakeAndDelegate, unstake... functions were moved to the Stargate.
    /// Since up until now we were using the StagateNFT contract to handle the VET,
    /// we need to transfer back all the previous staked VET to the Stargate
    /// so user can delegate it and unstake it. This functions transfers all the VET
    /// to the Stargate contract in one go.
    /// This function is called by the admin after the upgrade to V3 and the
    /// Stargate variable is set to the correct value
    /// @dev Only the DEFAULT_ADMIN_ROLE can call this function
    /// @dev Reverts with {IStargateNFT.VetTransferFailed} if the transfer fails
    function transferBalance(uint256 amount) external;

    /// @notice Migrate a token manager to the StargateNFT contract, this function is only callable by the TOKEN_MANAGER_MIGRATOR_ROLE
    /// so we can migrate the storage from NodeManagementV3 to StargateNFT, after the migration we can remove this function
    /// @param _tokenId The ID of the token to migrate
    /// @param _manager The address of the manager to migrate
    function migrateTokenManager(uint256 _tokenId, address _manager) external;
}

